// Writes src/version.ts from package.json, so the extension reports the version it was published as.
// Runs as part of `npm run build`; src/version.ts is generated and not committed. Bump package.json instead.
import { existsSync, readFileSync, writeFileSync } from "fs";
import path from "path";
import { fileURLToPath } from "url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const { version } = JSON.parse(readFileSync(path.join(root, "package.json"), "utf8"));
const out = path.join(root, "src", "version.ts");
const text =
  "// GENERATED by scripts/gen-version.mjs from package.json. Do not edit; bump package.json instead.\n" +
  `export const EXTENSION_VERSION = "${version}";\n`;
if (!existsSync(out) || readFileSync(out, "utf8") !== text) writeFileSync(out, text);
